// Display copies are generated by `npm run images` (scripts/make-images.mjs):
// /products/x.png → /products/thumb/x.webp (360px) or /products/large/x.webp (900px).
// Originals stay untouched so they match the CRAZYMIKE package byte-for-byte.

export type ImageSize = 'thumb' | 'large'

export const IMAGE_PIXELS: Record<ImageSize, number> = { thumb: 360, large: 900 }

export function displayImage(src: string, size: ImageSize): string {
  const slash = src.lastIndexOf('/')
  const name = src.slice(slash + 1).replace(/\.[^.]+$/, '.webp')
  return `${src.slice(0, slash)}/${size}/${name}`
}
